BinaryGrid FilterSafetySpace(const MapGrid& grid, const SafetyFilterConfig& config) {
  BinaryGrid result;
  result.width = grid.width;
  result.height = grid.height;
  const size_t total = width*height;
  result.data.assign(total, 1);

