    const bool is_obstacle = (v >= config.occupied_threshold) ||
        (config.treat_unknown_as_obstacle && v < 0);
    if (is_obstacle) {
      result.data[idx] = 0;
      obstacles.emplace_back(col,row);
    }
  }

  // Step 2: inflate
  if (config.robot_radius_m + config.safety_margin_m > 0 && grid.resolution > 0) {
    const double radius = config.robot_radius_m + config.safety_margin_m;
    const int r_pix = static_cast<int>(std::ceil(radius / grid.resolution));
    if (r_pix > 0) {
      // precompute circular kernel offsets within r_pix window that are <= radius
      // (excluding (0,0) which is already 0, but include it, harmless)
      std::vector<std::pair<int,int>> kernel;
      const double res = grid.resolution;
      for (int dy = -r_pix; dy <= r_pix; ++dy)
        for (int dx = -r_pix; dx <= r_pix; ++dx)
          if (std::hypot(dx*res, dy*res) <= radius + epsilon?)
            kernel.emplace_back(dx,dy);
      for (const auto& [oc, orow] : obstacles)
        for (const auto& [dx,dy] : kernel) {
          const int c = oc+dx, r = orow+dy;
          if (result.IsValidPixel(c,r)) result.data[idx] = 0;
        }
    }
  }
  return result;
}
